import React, { useEffect, useRef, useState } from 'react';
import { Alert, AppState, Button, ScrollView, StyleSheet, Text, View } from 'react-native';
import { StatusBar } from 'expo-status-bar';
import type { ExperimentConfig, TestNote } from '@/types';
import { ENGINE_OPTIONS, LOCALE_OPTIONS, POLICY_OPTIONS, START_MODE_OPTIONS } from '@/config/options';
import { getAdapter } from '@/engines/engineRegistry';
import { usePersistentRecorder } from '@/hooks/usePersistentRecorder';
import { copyToPersistentAudioFile } from '@/storage/files';
import { ensureVoiceLabDirs, copiedAudioUri, extensionFromUri, resultJsonUri } from '@/storage/paths';
import { clearNotes, loadNotes, patchNote, upsertNote } from '@/storage/noteStore';
import { NoteCard } from '@/ui/NoteCard';
import { PickerRow } from '@/ui/PickerRow';
import { makeId, msBetween, nowIso, safeError } from '@/utils/time';
import { resumePendingTranscriptions } from '@/workflow/resumePending';
import { transcribeNote } from '@/workflow/transcriptionQueue';

type LiveController = Awaited<ReturnType<NonNullable<ReturnType<typeof getAdapter>['startLive']>>>;

export default function App() {
  const recorder = usePersistentRecorder();
  const [config, setConfig] = useState<ExperimentConfig>({
    engineId: 'native-speech',
    policy: 'on-device',
    startMode: 'batch',
    locale: 'ru-RU'
  });
  const [notes, setNotes] = useState<TestNote[]>([]);
  const [activeNote, setActiveNote] = useState<TestNote | null>(null);
  const [busy, setBusy] = useState(false);
  const liveControllerRef = useRef<LiveController | null>(null);

  useEffect(() => {
    (async () => {
      await ensureVoiceLabDirs();
      setNotes(await loadNotes());
      const resumed = await resumePendingTranscriptions();
      if (resumed.length) setNotes(await loadNotes());
    })();
  }, []);

  useEffect(() => {
    const sub = AppState.addEventListener('change', async (state) => {
      if (state !== 'active' && activeNote) {
        await patchNote(activeNote.id, { wasBackgrounded: true });
        setNotes(await loadNotes());
      }
    });
    return () => sub.remove();
  }, [activeNote]);

  async function refresh() {
    setNotes(await loadNotes());
  }

  async function start() {
    try {
      setBusy(true);
      const now = nowIso();
      const note: TestNote = {
        id: makeId(),
        createdAt: now,
        updatedAt: now,
        status: 'recording',
        config,
        resultJsonUri: resultJsonUri(makeId('result_tmp')),
        attemptCount: 0,
        wasBackgrounded: false,
        metrics: { recordStartedAt: now }
      };
      note.resultJsonUri = resultJsonUri(note.id);

      const saved = await upsertNote(note);
      setActiveNote(saved);
      setNotes(await loadNotes());

      if (config.startMode === 'live') {
        const adapter = getAdapter(config.engineId, 'live');
        if (!adapter.startLive) throw new Error(`${adapter.label} does not support live mode.`);

        liveControllerRef.current = await adapter.startLive({
          note: saved,
          locale: config.locale,
          policy: config.policy,
          onPartial: async (text) => {
            await patchNote(saved.id, {
              partialTranscript: text,
              metrics: {
                ...saved.metrics,
                timeToFirstPartialMs: saved.metrics.timeToFirstPartialMs ?? msBetween(saved.metrics.recordStartedAt, nowIso())
              }
            });
            refresh();
          },
          onFinal: async (text) => {
            await patchNote(saved.id, { finalTranscript: text });
            refresh();
          }
        });
      } else {
        await recorder.start();
      }
    } catch (error) {
      Alert.alert('Start failed', safeError(error));
    } finally {
      setBusy(false);
    }
  }

  async function stop() {
    if (!activeNote) return;
    try {
      setBusy(true);
      const stoppedAt = nowIso();
      const durationMs = msBetween(activeNote.metrics.recordStartedAt, stoppedAt);

      if (activeNote.config.startMode === 'live') {
        const live = liveControllerRef.current;
        liveControllerRef.current = null;
        if (!live) throw new Error('Live controller missing.');

        const { audioUri, result } = await live.stop();
        const finishedAt = nowIso();
        await patchNote(activeNote.id, {
          status: 'transcribed',
          audioUri,
          finalTranscript: result.text,
          durationMs,
          metrics: {
            ...activeNote.metrics,
            recordStoppedAt: stoppedAt,
            transcribeFinishedAt: finishedAt,
            stopToFinalMs: msBetween(stoppedAt, finishedAt)
          }
        });
      } else {
        const tempUri = await recorder.stop();
        if (!tempUri) throw new Error('Recorder did not return an audio URI.');

        const targetAudioUri = copiedAudioUri(activeNote.id, extensionFromUri(tempUri));
        await copyToPersistentAudioFile(tempUri, targetAudioUri);

        const recorded = await patchNote(activeNote.id, {
          status: 'recorded',
          audioUri: targetAudioUri,
          durationMs,
          metrics: { ...activeNote.metrics, recordStoppedAt: stoppedAt }
        });
        if (!recorded) throw new Error('Failed to save note after recording.');

        // Start immediately. If iOS backgrounds the app, native adapter gets a short background window.
        await transcribeNote(recorded);
      }

      setActiveNote(null);
      await refresh();
    } catch (error) {
      await patchNote(activeNote.id, { status: 'pending_retry', error: safeError(error) });
      Alert.alert('Stop/transcribe failed', safeError(error));
      setActiveNote(null);
      await refresh();
    } finally {
      setBusy(false);
    }
  }

  async function retryPending() {
    setBusy(true);
    try {
      const fresh = await loadNotes();
      for (const note of fresh.filter((n) => ['recorded', 'pending_retry', 'transcribing'].includes(n.status))) {
        await transcribeNote(note);
      }
      await refresh();
    } catch (error) {
      Alert.alert('Retry failed', safeError(error));
    } finally {
      setBusy(false);
    }
  }

  async function clearAll() {
    await clearNotes();
    setNotes([]);
  }

  const isRecording = !!activeNote;

  return (
    <View style={styles.root}>
      <StatusBar style="auto" />
      <ScrollView contentContainerStyle={styles.content}>
        <Text style={styles.h1}>Voice Lab Prototype</Text>
        <Text style={styles.copy}>Test matrix: engine × on-device/cloud × batch/live × background/resume.</Text>

        <PickerRow label="Engine" value={config.engineId} options={ENGINE_OPTIONS} onChange={(engineId) => setConfig({ ...config, engineId })} />
        <PickerRow label="Policy" value={config.policy} options={POLICY_OPTIONS} onChange={(policy) => setConfig({ ...config, policy })} />
        <PickerRow label="Start mode" value={config.startMode} options={START_MODE_OPTIONS} onChange={(startMode) => setConfig({ ...config, startMode })} />
        <PickerRow
          label="Locale"
          value={config.locale}
          options={LOCALE_OPTIONS.map((id) => ({ id, label: id }))}
          onChange={(locale) => setConfig({ ...config, locale })}
        />

        <View style={styles.buttons}>
          <Button title={isRecording ? 'Stop' : 'Record'} onPress={isRecording ? stop : start} disabled={busy} />
          <Button title="Retry pending" onPress={retryPending} disabled={busy || isRecording} />
          <Button title="Clear logs" onPress={clearAll} disabled={busy || isRecording} />
        </View>

        {isRecording && <Text style={styles.recording}>Recording… {Math.round((recorder.state.durationMillis ?? 0) / 1000)}s</Text>}

        <Text style={styles.h2}>Notes / logs</Text>
        {notes.map((note) => <NoteCard key={note.id} note={note} />)}
      </ScrollView>
    </View>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1, backgroundColor: 'white' },
  content: { padding: 18, paddingTop: 60 },
  h1: { fontSize: 26, fontWeight: '900', marginBottom: 8 },
  h2: { fontSize: 18, fontWeight: '800', marginTop: 20, marginBottom: 12 },
  copy: { color: '#555', marginBottom: 18 },
  buttons: { gap: 10, marginVertical: 12 },
  recording: { fontWeight: '800', marginVertical: 12 }
});

