import type { EngineId, StartMode, TranscriptionAdapter } from '@/types';
import { nativeSpeechFileAdapter } from './nativeSpeechFile';
import { nativeSpeechLiveAdapter } from './nativeSpeechLive';
import { whisperBaseAdapter, whisperTinyAdapter } from './whisperFile';
import { whisperLiveScaffoldAdapter } from './whisperLiveScaffold';

export function getAdapter(engineId: EngineId, startMode: StartMode): TranscriptionAdapter {
  if (engineId === 'native-speech') {
    return startMode === 'live' ? nativeSpeechLiveAdapter : nativeSpeechFileAdapter;
  }
  if (engineId === 'whisper-tiny') return whisperTinyAdapter;
  if (engineId === 'whisper-base') return whisperBaseAdapter;
  return whisperLiveScaffoldAdapter;
}

