import { Platform } from 'react-native';
import { BackgroundTranscription } from 'background-transcription';
import type { RecognitionPolicy, TestNote, TranscriptResult, TranscriptionAdapter } from '@/types';
import { readJson } from '@/storage/files';

type NativeJson = {
  text: string;
  locale: string;
  requiresOnDeviceRecognition: boolean;
  resultJsonUri: string;
  startedAtMs: number;
  finishedAtMs: number;
};

async function ensureNativeSpeechReady(locale: string, policy: RecognitionPolicy) {
  if (Platform.OS !== 'ios') {
    throw new Error('Native Speech file transcription is iOS-only in this prototype.');
  }

  if (policy === 'on-device') {
    const ok = await BackgroundTranscription.supportsOnDeviceRecognition(locale);
    if (!ok) throw new Error(`On-device speech recognition is not available for ${locale}.`);
    return;
  }

  const status = await BackgroundTranscription.requestSpeechAuthorization();
  if (status !== 'authorized') {
    throw new Error(`Speech recognition permission not authorized: ${status}`);
  }
}

export const nativeSpeechFileAdapter: TranscriptionAdapter = {
  id: 'native-speech',
  label: 'Native Speech batch',
  supportsBatch: true,
  supportsLive: true,

  async transcribeFile({ audioUri, resultJsonUri, locale, policy }): Promise<TranscriptResult> {
    await ensureNativeSpeechReady(locale, policy);

    const payload = await BackgroundTranscription.transcribeFileToJson(
      audioUri,
      resultJsonUri,
      locale,
      policy === 'on-device',
      true
    );

    // Prefer the file written by native code. It makes resume-after-background easier to test.
    const filePayload = await readJson<NativeJson>(resultJsonUri);
    return {
      text: filePayload?.text ?? payload.text,
      raw: filePayload ?? payload
    };
  }
};

export async function readNativeResultJson(note: TestNote): Promise<TranscriptResult | null> {
  if (!note.resultJsonUri) return null;
  const payload = await readJson<NativeJson>(note.resultJsonUri);
  if (!payload?.text) return null;
  return { text: payload.text, raw: payload };
}

