import { initWhisper } from 'whisper.rn';
import * as FileSystem from 'expo-file-system/legacy';
import type { TranscriptionAdapter } from '@/types';
import { WHISPER_MODEL_URIS } from '@/config/models';
import { writeJson } from '@/storage/files';

const contextCache = new Map<string, Awaited<ReturnType<typeof initWhisper>>>();

async function getContext(modelUri: string) {
  const info = await FileSystem.getInfoAsync(modelUri);
  if (!info.exists) {
    throw new Error(`Whisper model not found at ${modelUri}. Copy the ggml model into DocumentDirectory/voice-lab/models/.`);
  }

  const cached = contextCache.get(modelUri);
  if (cached) return cached;

  const context = await initWhisper({ filePath: modelUri });
  contextCache.set(modelUri, context);
  return context;
}

function makeWhisperAdapter(kind: 'tiny' | 'base'): TranscriptionAdapter {
  return {
    id: kind === 'tiny' ? 'whisper-tiny' : 'whisper-base',
    label: `Whisper ${kind}`,
    supportsBatch: true,
    supportsLive: false,

    async transcribeFile({ audioUri, resultJsonUri, locale }) {
      const context = await getContext(WHISPER_MODEL_URIS[kind]);
      const language = locale.split('-')[0] || 'ru';

      const { promise } = context.transcribe(audioUri, {
        language,
        // Keep this explicit for repeatable experiments.
        translate: false
      });

      const result = await promise;
      const text = result.result ?? '';

      await writeJson(resultJsonUri, {
        text,
        engine: `whisper-${kind}`,
        locale,
        language,
        raw: result,
        finishedAtMs: Date.now()
      });

      return { text, raw: result };
    }
  };
}

export const whisperTinyAdapter = makeWhisperAdapter('tiny');
export const whisperBaseAdapter = makeWhisperAdapter('base');

