import * as FileSystem from 'expo-file-system/legacy';

export const ROOT_DIR = `${FileSystem.documentDirectory}voice-lab/`;
export const AUDIO_DIR = `${ROOT_DIR}audio/`;
export const RESULT_DIR = `${ROOT_DIR}results/`;
export const MODEL_DIR = `${ROOT_DIR}models/`;
export const VAD_DIR = `${ROOT_DIR}vad/`;

export async function ensureVoiceLabDirs() {
  for (const uri of [ROOT_DIR, AUDIO_DIR, RESULT_DIR, MODEL_DIR, VAD_DIR]) {
    const info = await FileSystem.getInfoAsync(uri);
    if (!info.exists) {
      await FileSystem.makeDirectoryAsync(uri, { intermediates: true });
    }
  }
}

export function resultJsonUri(noteId: string) {
  return `${RESULT_DIR}${noteId}.json`;
}

export function copiedAudioUri(noteId: string, ext = 'm4a') {
  return `${AUDIO_DIR}${noteId}.${ext.replace('.', '')}`;
}

export function extensionFromUri(uri: string) {
  const clean = uri.split('?')[0] ?? uri;
  const ext = clean.split('.').pop();
  return ext && ext.length <= 5 ? ext : 'm4a';
}

