import * as FileSystem from 'expo-file-system/legacy';
import { ensureVoiceLabDirs } from './paths';

export async function copyToPersistentAudioFile(sourceUri: string, targetUri: string) {
  await ensureVoiceLabDirs();
  const targetInfo = await FileSystem.getInfoAsync(targetUri);
  if (targetInfo.exists) await FileSystem.deleteAsync(targetUri, { idempotent: true });
  await FileSystem.copyAsync({ from: sourceUri, to: targetUri });
  return targetUri;
}

export async function writeJson(uri: string, value: unknown) {
  await ensureVoiceLabDirs();
  await FileSystem.writeAsStringAsync(uri, JSON.stringify(value, null, 2));
}

export async function readJson<T>(uri: string): Promise<T | null> {
  const info = await FileSystem.getInfoAsync(uri);
  if (!info.exists) return null;
  const raw = await FileSystem.readAsStringAsync(uri);
  return JSON.parse(raw) as T;
}

export async function exists(uri?: string) {
  if (!uri) return false;
  return (await FileSystem.getInfoAsync(uri)).exists;
}

