import AsyncStorage from '@react-native-async-storage/async-storage';
import type { NoteStatus, TestNote } from '@/types';
import { nowIso } from '@/utils/time';

const NOTES_KEY = 'voice-lab:notes:v1';

export async function loadNotes(): Promise<TestNote[]> {
  const raw = await AsyncStorage.getItem(NOTES_KEY);
  if (!raw) return [];
  return JSON.parse(raw) as TestNote[];
}

export async function saveNotes(notes: TestNote[]) {
  await AsyncStorage.setItem(NOTES_KEY, JSON.stringify(notes));
}

export async function upsertNote(note: TestNote) {
  const notes = await loadNotes();
  const index = notes.findIndex((n) => n.id === note.id);
  const next = { ...note, updatedAt: nowIso() };
  if (index >= 0) notes[index] = next;
  else notes.unshift(next);
  await saveNotes(notes.slice(0, 100));
  return next;
}

export async function patchNote(id: string, patch: Partial<TestNote>) {
  const notes = await loadNotes();
  const index = notes.findIndex((n) => n.id === id);
  if (index < 0) return null;
  const next = { ...notes[index], ...patch, updatedAt: nowIso() };
  notes[index] = next;
  await saveNotes(notes);
  return next;
}

export async function findPendingNotes() {
  const notes = await loadNotes();
  const pending: NoteStatus[] = ['recorded', 'transcribing', 'pending_retry'];
  return notes.filter((n) => pending.includes(n.status) && !!n.audioUri);
}

export async function clearNotes() {
  await AsyncStorage.removeItem(NOTES_KEY);
}

