import type { TestNote, TranscriptResult } from '@/types';
import { getAdapter } from '@/engines/engineRegistry';
import { readNativeResultJson } from '@/engines/nativeSpeechFile';
import { patchNote } from '@/storage/noteStore';
import { exists } from '@/storage/files';
import { msBetween, nowIso, safeError } from '@/utils/time';

export async function transcribeNote(note: TestNote): Promise<TestNote> {
  if (!note.audioUri || !note.resultJsonUri) {
    throw new Error(`Note ${note.id} has no audioUri/resultJsonUri.`);
  }

  const audioExists = await exists(note.audioUri);
  if (!audioExists) {
    const failed = await patchNote(note.id, {
      status: 'failed',
      error: `Audio file missing: ${note.audioUri}`
    });
    if (!failed) throw new Error('Failed to patch note.');
    return failed;
  }

  const startedAt = nowIso();
  const nextAttempt = note.attemptCount + 1;
  await patchNote(note.id, {
    status: 'transcribing',
    attemptCount: nextAttempt,
    metrics: { ...note.metrics, transcribeStartedAt: startedAt }
  });

  try {
    const adapter = getAdapter(note.config.engineId, 'batch');
    if (!adapter.transcribeFile) throw new Error(`${adapter.label} does not support batch transcription.`);

    const result = await adapter.transcribeFile({
      note,
      audioUri: note.audioUri,
      resultJsonUri: note.resultJsonUri,
      locale: note.config.locale,
      policy: note.config.policy
    });

    return await completeNote(note, result, startedAt);
  } catch (error) {
    // Native iOS may have written result JSON even if JS promise got interrupted/replayed weirdly.
    const nativeResult = await readNativeResultJson(note);
    if (nativeResult) return await completeNote(note, nativeResult, startedAt);

    const patched = await patchNote(note.id, {
      status: 'pending_retry',
      error: safeError(error),
      attemptCount: nextAttempt
    });
    if (!patched) throw error;
    return patched;
  }
}

async function completeNote(note: TestNote, result: TranscriptResult, startedAt: string) {
  const finishedAt = nowIso();
  const total = msBetween(startedAt, finishedAt);
  const stoppedToFinal = msBetween(note.metrics.recordStoppedAt, finishedAt);
  const rtf = note.durationMs && total ? total / note.durationMs : undefined;

  const patched = await patchNote(note.id, {
    status: 'transcribed',
    finalTranscript: result.text,
    error: undefined,
    metrics: {
      ...note.metrics,
      transcribeStartedAt: startedAt,
      transcribeFinishedAt: finishedAt,
      totalTranscriptionMs: total,
      stopToFinalMs: stoppedToFinal,
      realtimeFactor: rtf
    }
  });

  if (!patched) throw new Error('Failed to patch completed note.');
  return patched;
}

