import { findPendingNotes, patchNote } from '@/storage/noteStore';
import { transcribeNote } from './transcriptionQueue';

export async function resumePendingTranscriptions() {
  const pending = await findPendingNotes();
  const results = [];

  for (const note of pending) {
    const marked = await patchNote(note.id, { resumedAfterLaunch: true, status: 'pending_retry' });
    if (!marked) continue;
    try {
      results.push(await transcribeNote(marked));
    } catch (error) {
      console.warn('resume failed', note.id, error);
    }
  }

  return results;
}

