import { useEffect } from 'react';
import { Alert } from 'react-native';
import {
  AudioModule,
  RecordingPresets,
  setAudioModeAsync,
  useAudioRecorder,
  useAudioRecorderState
} from 'expo-audio';

export function usePersistentRecorder() {
  const recorder = useAudioRecorder({
    ...RecordingPresets.HIGH_QUALITY,
    directory: 'document'
  });
  const state = useAudioRecorderState(recorder, 300);

  useEffect(() => {
    (async () => {
      const status = await AudioModule.requestRecordingPermissionsAsync();
      if (!status.granted) {
        Alert.alert('Microphone permission denied');
      }

      await setAudioModeAsync({
        playsInSilentMode: true,
        allowsRecording: true,
        allowsBackgroundRecording: true
      });
    })();
  }, []);

  async function start() {
    await recorder.prepareToRecordAsync({ directory: 'document' });
    recorder.record();
  }

  async function stop() {
    await recorder.stop();
    return recorder.uri ?? state.url ?? undefined;
  }

  return { recorder, state, start, stop };
}

