import React from 'react';
import { StyleSheet, Text, View } from 'react-native';
import type { TestNote } from '@/types';

export function NoteCard({ note }: { note: TestNote }) {
  const config = `${note.config.engineId} / ${note.config.policy} / ${note.config.startMode} / ${note.config.locale}`;
  const ms = note.metrics.totalTranscriptionMs;
  const rtf = note.metrics.realtimeFactor;

