import { Platform } from 'react-native';
import { ExpoSpeechRecognitionModule } from 'expo-speech-recognition';
import type { RecognitionPolicy, TranscriptionAdapter } from '@/types';
import { AUDIO_DIR } from '@/storage/paths';

async function requestPermissions(policy: RecognitionPolicy) {
  if (policy === 'cloud-allowed' && Platform.OS === 'ios') {
    const speech = await ExpoSpeechRecognitionModule.requestSpeechRecognizerPermissionsAsync();
    if (!speech.granted) throw new Error(`Speech permission denied: ${speech.status}`);
  }

  const mic = await ExpoSpeechRecognitionModule.requestMicrophonePermissionsAsync();
  if (!mic.granted) throw new Error(`Microphone permission denied: ${mic.status}`);
}

export const nativeSpeechLiveAdapter: TranscriptionAdapter = {
  id: 'native-speech',
  label: 'Native Speech live',
  supportsBatch: true,
  supportsLive: true,

  async startLive({ note, locale, policy, onPartial, onFinal }) {
    await requestPermissions(policy);

    if (policy === 'on-device') {
      const supported = ExpoSpeechRecognitionModule.supportsOnDeviceRecognition();
      if (!supported) throw new Error('On-device recognition is not supported by this device/service.');
    }

    let latestText = '';
    let finalText = '';
    let audioUri: string | undefined;
    let firstResultResolved = false;

    const listeners = [
      ExpoSpeechRecognitionModule.addListener('result', (event: any) => {
        const text = event.results?.[0]?.transcript ?? '';
        if (!text) return;
        latestText = text;
        onPartial(text);
        if (!firstResultResolved) firstResultResolved = true;
        if (event.isFinal) {
          finalText = text;
          onFinal?.(text);
        }
      }),
      ExpoSpeechRecognitionModule.addListener('audioend', (event: { uri?: string | null }) => {
        audioUri = event.uri ?? undefined;
      }),
      ExpoSpeechRecognitionModule.addListener('error', (event: any) => {
        console.warn('native live speech error', event.error, event.message);
      })
    ];

    ExpoSpeechRecognitionModule.start({
      lang: locale,
      interimResults: true,
      continuous: true,
      requiresOnDeviceRecognition: policy === 'on-device',
      recordingOptions: {
        persist: true,
        outputDirectory: AUDIO_DIR,
        outputFileName: `${note.id}.wav`,
        outputSampleRate: 16000,
        outputEncoding: 'pcmFormatInt16'
      }
    });

    return {
      stop: async () => {
        await new Promise<void>((resolve) => {
          const endListener = ExpoSpeechRecognitionModule.addListener('end', () => {
            endListener.remove();
            resolve();
          });
          ExpoSpeechRecognitionModule.stop();
          setTimeout(resolve, 5000);
        });
        listeners.forEach((l) => l.remove());
        return {
          audioUri,
          result: { text: finalText || latestText }
        };
      }
    };
  }
};

