import AsyncStorage from '@react-native-async-storage/async-storage';
import type { CloudProviderId } from '@/types';

export type ProviderSettings = Record<CloudProviderId, string>;

const SETTINGS_KEY = 'voice-lab:provider-keys:v1';

const EMPTY_SETTINGS: ProviderSettings = {
  openai: '',
  elevenlabs: '',
  deepgram: ''
};

export async function loadProviderSettings(): Promise<ProviderSettings> {
  const raw = await AsyncStorage.getItem(SETTINGS_KEY);
  if (!raw) return EMPTY_SETTINGS;
  return { ...EMPTY_SETTINGS, ...(JSON.parse(raw) as Partial<ProviderSettings>) };
}

export async function saveProviderSettings(settings: ProviderSettings) {
  await AsyncStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
}

export async function getProviderApiKey(provider: CloudProviderId) {
  const settings = await loadProviderSettings();
  const key = settings[provider]?.trim();
  if (!key) {
    throw new Error(`Missing ${provider} API key. Add it in Provider API keys.`);
  }
  return key;
}

