import { Buffer } from 'buffer';
import * as FileSystem from 'expo-file-system/legacy';
import type { CloudProviderId, TranscriptionAdapter, TranscriptResult } from '@/types';
import { getProviderApiKey } from '@/storage/settings';
import { writeJson } from '@/storage/files';
import { startLivePcmStream, type LivePcmStream } from './liveAudioStream';

type SocketFactoryOptions = { headers?: Record<string, string> };
type LiveProvider = CloudProviderId;

const LIVE_SAMPLE_RATE: Record<LiveProvider, number> = {
  openai: 24000,
  elevenlabs: 16000,
  deepgram: 16000
};

function languageFromLocale(locale: string) {
  return locale.split('-')[0] || 'en';
}

function fileNameFromUri(uri: string) {
  const clean = uri.split('?')[0] ?? uri;
  return clean.split('/').pop() || 'audio.m4a';
}

function mimeFromUri(uri: string) {
  const ext = fileNameFromUri(uri).split('.').pop()?.toLowerCase();
  if (ext === 'wav') return 'audio/wav';
  if (ext === 'mp3') return 'audio/mpeg';
  if (ext === 'webm') return 'audio/webm';
  if (ext === 'ogg') return 'audio/ogg';
  if (ext === 'mp4') return 'audio/mp4';
  return 'audio/m4a';
}

function assertOk(response: Response, provider: string) {
  if (!response.ok) {
    throw new Error(`${provider} STT failed: HTTP ${response.status}`);
  }
}

function appendFile(form: FormData, audioUri: string) {
  form.append('file', {
    uri: audioUri,
    name: fileNameFromUri(audioUri),
    type: mimeFromUri(audioUri)
  } as any);
}

async function transcribeOpenAiFile(audioUri: string, resultJsonUri: string, locale: string): Promise<TranscriptResult> {
  const apiKey = await getProviderApiKey('openai');
  const form = new FormData();
  appendFile(form, audioUri);
  form.append('model', 'gpt-4o-transcribe');
  form.append('language', languageFromLocale(locale));
  form.append('response_format', 'json');

  const response = await fetch('https://api.openai.com/v1/audio/transcriptions', {
    method: 'POST',
    headers: { Authorization: `Bearer ${apiKey}` },
    body: form
  });
  assertOk(response, 'OpenAI');
  const json = await response.json();
  const text = json.text ?? '';
  await writeJson(resultJsonUri, { provider: 'openai', model: 'gpt-4o-transcribe', locale, text, raw: json, finishedAtMs: Date.now() });
  return { text, raw: json };
}

async function transcribeElevenLabsFile(audioUri: string, resultJsonUri: string, locale: string): Promise<TranscriptResult> {
  const apiKey = await getProviderApiKey('elevenlabs');
  const form = new FormData();
  appendFile(form, audioUri);
  form.append('model_id', 'scribe_v2');
  form.append('language_code', languageFromLocale(locale));
  form.append('timestamps_granularity', 'word');
  form.append('diarize', 'false');

  const response = await fetch('https://api.elevenlabs.io/v1/speech-to-text', {
    method: 'POST',
    headers: { 'xi-api-key': apiKey },
    body: form
  });
  assertOk(response, 'ElevenLabs');
  const json = await response.json();
  const text = json.text ?? '';
  await writeJson(resultJsonUri, { provider: 'elevenlabs', model: 'scribe_v2', locale, text, raw: json, finishedAtMs: Date.now() });
  return { text, raw: json };
}

async function transcribeDeepgramFile(audioUri: string, resultJsonUri: string, locale: string): Promise<TranscriptResult> {
  const apiKey = await getProviderApiKey('deepgram');
  const query = new URLSearchParams({
    model: 'nova-3',
    language: locale,
    smart_format: 'true',
    punctuate: 'true'
  });
  const response = await FileSystem.uploadAsync(`https://api.deepgram.com/v1/listen?${query.toString()}`, audioUri, {
    httpMethod: 'POST',
    uploadType: FileSystem.FileSystemUploadType.BINARY_CONTENT,
    mimeType: mimeFromUri(audioUri),
    headers: {
      Authorization: `Token ${apiKey}`
    }
  });
  if (response.status < 200 || response.status >= 300) {
    throw new Error(`Deepgram STT failed: HTTP ${response.status}`);
  }
  const json = JSON.parse(response.body);
  const text = json.results?.channels?.[0]?.alternatives?.[0]?.transcript ?? '';
  await writeJson(resultJsonUri, { provider: 'deepgram', model: 'nova-3', locale, text, raw: json, finishedAtMs: Date.now() });
  return { text, raw: json };
}

function makeSocket(url: string, options?: SocketFactoryOptions): WebSocket {
  return new (WebSocket as any)(url, undefined, options);
}

function waitForOpen(ws: WebSocket, provider: string) {
  return new Promise<void>((resolve, reject) => {
    const timeout = setTimeout(() => reject(new Error(`${provider} live socket timed out.`)), 12000);
    ws.onopen = () => {
      clearTimeout(timeout);
      resolve();
    };
    ws.onerror = () => {
      clearTimeout(timeout);
      reject(new Error(`${provider} live socket failed to connect.`));
    };
  });
}

function parseSocketMessage(event: WebSocketMessageEvent) {
  if (typeof event.data === 'string') return JSON.parse(event.data);
  return null;
}

function base64ToArrayBuffer(base64: string) {
  const buffer = Buffer.from(base64, 'base64');
  return buffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength);
}

async function startOpenAiLive({
  locale,
  onPartial,
  onFinal
}: {
  locale: string;
  onPartial: (text: string) => void;
  onFinal?: (text: string) => void;
}) {
  const apiKey = await getProviderApiKey('openai');
  const sampleRate = LIVE_SAMPLE_RATE.openai;
  const ws = makeSocket('wss://api.openai.com/v1/realtime?model=gpt-realtime-whisper', {
    headers: { Authorization: `Bearer ${apiKey}` }
  });
  await waitForOpen(ws, 'OpenAI');

  const segments: string[] = [];
  let current = '';
  let sentSinceCommit = false;
  let stream: LivePcmStream | null = null;
  let commitTimer: ReturnType<typeof setInterval> | null = null;

  ws.onmessage = (event) => {
    const message = parseSocketMessage(event);
    if (!message) return;
    if (message.type === 'conversation.item.input_audio_transcription.delta') {
      current += message.delta ?? '';
      onPartial([...segments, current].filter(Boolean).join(' '));
    }
    if (message.type === 'conversation.item.input_audio_transcription.completed') {
      const text = message.transcript || current;
      if (text) segments.push(text);
      current = '';
      onFinal?.(segments.join(' '));
    }
    if (message.type === 'error') {
      console.warn('OpenAI live error', message.error ?? message);
    }
  };

  ws.send(JSON.stringify({
    type: 'session.update',
    session: {
      type: 'transcription',
      audio: {
        input: {
          format: { type: 'audio/pcm', rate: sampleRate },
          transcription: {
            model: 'gpt-realtime-whisper',
            language: languageFromLocale(locale),
            delay: 'low'
          }
        }
      }
    }
  }));

  const commit = () => {
    if (ws.readyState === WebSocket.OPEN && sentSinceCommit) {
      ws.send(JSON.stringify({ type: 'input_audio_buffer.commit' }));
      sentSinceCommit = false;
    }
  };

  stream = startLivePcmStream({
    sampleRate,
    onChunk: (audio) => {
      if (ws.readyState !== WebSocket.OPEN) return;
      sentSinceCommit = true;
      ws.send(JSON.stringify({ type: 'input_audio_buffer.append', audio }));
    }
  });
  commitTimer = setInterval(commit, 1800);

  return {
    stop: async () => {
      if (commitTimer) clearInterval(commitTimer);
      await stream?.stop();
      commit();
      await new Promise((resolve) => setTimeout(resolve, 2500));
      ws.close();
      const text = [...segments, current].filter(Boolean).join(' ');
      return { result: { text, raw: { provider: 'openai-live', sampleRate } } };
    }
  };
}

