import * as FileSystem from 'expo-file-system/legacy';
import * as Sharing from 'expo-sharing';
import JSZip from 'jszip';
import { loadNotes } from './noteStore';
import { ensureVoiceLabDirs, EXPORT_DIR } from './paths';
import { readJson } from './files';

function basename(uri: string) {
  const clean = uri.split('?')[0] ?? uri;
  return clean.split('/').pop() || 'file';
}

async function addFileIfExists(zip: JSZip, zipPath: string, uri?: string) {
  if (!uri) return;
  const info = await FileSystem.getInfoAsync(uri);
  if (!info.exists) return;
  const base64 = await FileSystem.readAsStringAsync(uri, { encoding: FileSystem.EncodingType.Base64 });
  zip.file(zipPath, base64, { base64: true });
}

export async function exportVoiceLabArchive() {
  await ensureVoiceLabDirs();
  const notes = await loadNotes();
  const zip = new JSZip();

  zip.file('notes.json', JSON.stringify(notes, null, 2));

  for (const note of notes) {
    const prefix = `notes/${note.id}`;
    if (note.resultJsonUri) {
      const result = await readJson(note.resultJsonUri);
      if (result) zip.file(`${prefix}/result.json`, JSON.stringify(result, null, 2));
    }
    await addFileIfExists(zip, `${prefix}/audio/${basename(note.audioUri ?? '')}`, note.audioUri);
  }

  const archiveBase64 = await zip.generateAsync({ type: 'base64' });
  const uri = `${EXPORT_DIR}voice-lab-export-${Date.now()}.zip`;
  await FileSystem.writeAsStringAsync(uri, archiveBase64, { encoding: FileSystem.EncodingType.Base64 });

  if (await Sharing.isAvailableAsync()) {
    await Sharing.shareAsync(uri, {
      mimeType: 'application/zip',
      dialogTitle: 'Export Voice Lab data'
    });
  }

  return uri;
}

