async function startDeepgramLive({
  locale,
  onPartial,
  onFinal
}: {
  locale: string;
  onPartial: (text: string) => void;
  onFinal?: (text: string) => void;
}) {
  const apiKey = await getProviderApiKey('deepgram');
  const sampleRate = LIVE_SAMPLE_RATE.deepgram;
  const query = new URLSearchParams({
    model: 'nova-3',
    language: locale,
    encoding: 'linear16',
    sample_rate: String(sampleRate),
    channels: '1',
    interim_results: 'true',
    endpointing: '300',
    smart_format: 'true',
    punctuate: 'true'
  });
  const ws = makeSocket(`wss://api.deepgram.com/v1/listen?${query.toString()}`, {
    headers: { Authorization: `Token ${apiKey}` }
  });
  await waitForOpen(ws, 'Deepgram');

  let partial = '';
  let final = '';
  const finalized: string[] = [];

  ws.onmessage = (event) => {
    const message = parseSocketMessage(event);
    if (!message || message.type !== 'Results') return;
    const text = message.channel?.alternatives?.[0]?.transcript ?? '';
    if (!text) return;
    if (message.is_final || message.speech_final) {
      finalized.push(text);
      final = finalized.join(' ');
      partial = '';
      onFinal?.(final);
    } else {
      partial = text;
      onPartial([final, partial].filter(Boolean).join(' '));
    }
  };

  const stream = startLivePcmStream({
    sampleRate,
    onChunk: (base64) => {
      if (ws.readyState !== WebSocket.OPEN) return;
      ws.send(base64ToArrayBuffer(base64));
    }
  });

  return {
    stop: async () => {
      await stream.stop();
      if (ws.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify({ type: 'Finalize' }));
      }
      await new Promise((resolve) => setTimeout(resolve, 1800));
      ws.close();
      return { result: { text: final || partial, raw: { provider: 'deepgram-live', sampleRate } } };
    }
  };
}

function makeCloudAdapter(provider: CloudProviderId): TranscriptionAdapter {
  const labels: Record<CloudProviderId, string> = {
    openai: 'OpenAI STT',
    elevenlabs: 'ElevenLabs STT',
    deepgram: 'Deepgram STT'
  };

  return {
    id: provider,
    label: labels[provider],
    supportsBatch: true,
    supportsLive: true,

    async transcribeFile({ audioUri, resultJsonUri, locale }) {
      if (provider === 'openai') return transcribeOpenAiFile(audioUri, resultJsonUri, locale);
      if (provider === 'elevenlabs') return transcribeElevenLabsFile(audioUri, resultJsonUri, locale);
      return transcribeDeepgramFile(audioUri, resultJsonUri, locale);
    },

    async startLive({ locale, onPartial, onFinal }) {
      if (provider === 'openai') return startOpenAiLive({ locale, onPartial, onFinal });
      if (provider === 'elevenlabs') return startElevenLabsLive({ locale, onPartial, onFinal });
      return startDeepgramLive({ locale, onPartial, onFinal });
    }
  };
}

export const openAiAdapter = makeCloudAdapter('openai');
export const elevenLabsAdapter = makeCloudAdapter('elevenlabs');
export const deepgramAdapter = makeCloudAdapter('deepgram');

