  return buffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength);
}

function arrayBufferToBase64(arrayBuffer: ArrayBuffer) {
  return Buffer.from(arrayBuffer).toString('base64');
}

export function useLiveAudioSources(): LiveAudioSourceController {
  const expoRouteRef = useRef<ExpoRoute | null>(null);
  const drStreamRef = useRef<ActiveDrStream | null>(null);

  const expo16 = useAudioStream({
    sampleRate: 16000,
    channels: 1,
    encoding: 'int16',
