      const route = expoRouteRef.current;
      if (!route || buffer.sampleRate !== 16000) return;
      route.onChunk({
        arrayBuffer: buffer.data,
        base64: arrayBufferToBase64(buffer.data),
        sampleRate: buffer.sampleRate,
        sourceId: route.sourceId
      });
    }
  });

