import React from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';

type Option<T extends string> = { id: T; label: string };

export function PickerRow<T extends string>({
  label,
  value,
  options,
  onChange
}: {
  label: string;
  value: T;
  options: Option<T>[];
  onChange: (value: T) => void;
}) {
  return (
    <View style={styles.wrap}>
      <Text style={styles.label}>{label}</Text>
      <View style={styles.options}>
        {options.map((option) => {
          const selected = option.id === value;
          return (
            <Pressable
              key={option.id}
              onPress={() => onChange(option.id)}
              style={[styles.option, selected && styles.selected]}
            >
              <Text style={[styles.optionText, selected && styles.selectedText]}>{option.label}</Text>
            </Pressable>
          );
        })}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  wrap: { gap: 8, marginBottom: 14 },
  label: { fontWeight: '700', fontSize: 14 },
  options: { flexDirection: 'row', flexWrap: 'wrap', gap: 8 },
  option: {
    borderWidth: 1,
    borderColor: '#999',
    borderRadius: 999,
    paddingHorizontal: 12,
    paddingVertical: 8
  },
  selected: { backgroundColor: '#111', borderColor: '#111' },
  optionText: { fontSize: 13 },
  selectedText: { color: 'white' }
});
import React from 'react';
import { StyleSheet, Text, View } from 'react-native';
import type { TestNote } from '@/types';

export function NoteCard({ note }: { note: TestNote }) {
  const liveSource = note.config.startMode === 'live' ? ` / ${note.config.liveAudioSource ?? 'unknown-source'}` : '';
  const config = `${note.config.engineId} / ${note.config.policy} / ${note.config.startMode}${liveSource} / ${note.config.locale}`;
  const ms = note.metrics.totalTranscriptionMs;
  const rtf = note.metrics.realtimeFactor;

  return (
    <View style={styles.card}>
      <Text style={styles.title}>{note.status.toUpperCase()} · {note.id}</Text>
      <Text style={styles.meta}>{config}</Text>
      {!!note.partialTranscript && <Text style={styles.partial}>Partial: {note.partialTranscript}</Text>}
      {!!note.finalTranscript && <Text style={styles.final}>{note.finalTranscript}</Text>}
      {!!note.error && <Text style={styles.error}>{note.error}</Text>}
      <Text style={styles.meta}>
        attempts: {note.attemptCount} · duration: {note.durationMs ? Math.round(note.durationMs / 1000) : '-'}s · transcribe: {ms ? `${ms}ms` : '-'} · rtf: {rtf ? rtf.toFixed(2) : '-'}
      </Text>
      <Text style={styles.meta} numberOfLines={1}>audio: {note.audioUri ?? '-'}</Text>
      <Text style={styles.meta} numberOfLines={1}>result: {note.resultJsonUri ?? '-'}</Text>
    </View>
  );
}

